reference_solution:
def integer_sqrt(x):
    left, right, answer = 0, x, 0
    while left <= right:
        middle = (left + right) // 2
        if middle == 0 or middle <= x // middle:
            answer = middle
            left = middle + 1
        else:
            right = middle - 1
    return answer

